_CPP_SRC = r"""
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups);
"""
_conv_cuda = load_inline(
    name="custom_conv2d_tiled",
    cpp_sources=[_CPP_SRC],
    cuda_sources=[_CUDA_SRC],
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None
            self.register_buffer("_empty_bias", torch.empty(0), persistent=False)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (in_channels // groups) * kernel_size * kernel_size
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias_arg = self.bias if self.bias is not None else self._empty_bias
        return _conv_cuda.conv2d_forward(
            x,
            self.weight,
            bias_arg,
            self.use_bias,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )

