#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#define TILE_OH 32
#define TILE_OW 16
#define OC_TILE 16
#define C_CHUNK 2
#define THREADS 256
// Optimization: vectorized (float4) global->shared staging of the input tile.
// The shared-memory input row stride is padded to a multiple of 4 floats so the
// dominant input-tile traffic uses 128-bit global loads and 128-bit shared-memory
// stores, cutting the number of memory transactions roughly 4x for that traffic
