      const int oc_local = idx / (C_CHUNK * kk);
      int rem = idx - oc_local * C_CHUNK * kk;
      const int c_local = rem / kk;
      rem -= c_local * kk;
      const int kh = rem / kernel_w;
      const int kw = rem - kh * kernel_w;
      const int oc = oc_base + oc_local;
      const int c = c_src + c_local;
      float v = 0.0f;
      if (oc < out_channels && c < in_channels) {
        v = weight[((oc * in_channels + c) * kernel_h + kh) * kernel_w + kw];
      }
      s_w[idx] = v;
    }
  };
  // Software pipeline (double buffering): prefetch the next input-channel chunk
  // into the alternate shared-memory buffer while computing on the current one.
  load_input_tile(0, s_in0);
  load_weight_tile(0, s_w0);
  __syncthreads();
  for (int c_base = 0; c_base < in_channels; c_base += C_CHUNK) {
    const int cur = (c_base / C_CHUNK) & 1;
    const int c_next = c_base + C_CHUNK;
    const float* s_in_c = cur ? s_in1 : s_in0;
    const float* s_w_c = cur ? s_w1 : s_w0;
    float* s_in_n = cur ? s_in0 : s_in1;
    float* s_w_n = cur ? s_w0 : s_w1;
    if (c_next < in_channels) {
      load_input_tile(c_next, s_in_n);
      load_weight_tile(c_next, s_w_n);
    }
    if (valid_spatial) {
      for (int kh = 0; kh < kernel_h; ++kh) {
        const int ih_local0 = ty * 2 * stride + kh * dilation;
        if (ih_local0 >= tile_in_h) continue;
        const int row_off = stride * tile_in_w_pad;
        for (int kw = 0; kw < kernel_w; ++kw) {
          const int iw_local0 = tx * 2 * stride + kw * dilation;
          if (iw_local0 >= tile_in_w) continue;
          const int s_in_base = ih_local0 * tile_in_w_pad + iw_local0;
          for (int c_local = 0; c_local < C_CHUNK; ++c_local) {
            const int c_off = c_local * s_in_plane + s_in_base;
            const float xv00 = s_in_c[c_off];
            const float xv01 = s_in_c[c_off + stride];
            const float xv10 = s_in_c[c_off + row_off];
            const float xv11 = s_in_c[c_off + row_off + stride];
            const int s_w_base = (c_local * kernel_h + kh) * kernel_w + kw;
#pragma unroll
            for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
              const float wv = s_w_c[oc_local * C_CHUNK * kk + s_w_base];
              acc[0][0][oc_local] += xv00 * wv;
              acc[0][1][oc_local] += xv01 * wv;
              acc[1][0][oc_local] += xv10 * wv;
              acc[1][1][oc_local] += xv11 * wv;
            }
          }
        }
      }
    }
    __syncthreads();
  }
  if (valid_spatial) {
#pragma unroll
    for (int dy = 0; dy < 2; ++dy) {
      const int oh = oh0 + dy;
      if (oh >= out_h) continue;
#pragma unroll
      for (int dx = 0; dx < 2; ++dx) {
        const int ow = ow0 + dx;
        if (ow >= out_w) continue;
#pragma unroll
        for (int oc_local = 0; oc_local < OC_TILE; ++oc_local) {
          const int oc = oc_base + oc_local;
          if (oc < out_channels) {
            float v = acc[dy][dx][oc_local];
            if (bias != nullptr) {
              v += bias[oc];
            }
            output[((n * out_channels + oc) * out_h + oh) * out_w + ow] = v;
          }
        }
      }
    }
  }
}
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups) {
  TORCH_CHECK(input.is_cuda(), "input must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
  TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
  TORCH_CHECK(input.dim() == 4, "input must be NCHW");
  TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
  TORCH_CHECK(groups == 1, "custom kernel currently supports groups == 1");
  const c10::cuda::CUDAGuard guard(input.device());
  auto x = input.contiguous();
  auto w = weight.contiguous();
  auto b = has_bias ? bias.contiguous() : bias;
  const int batch = static_cast<int>(x.size(0));
  const int in_channels = static_cast<int>(x.size(1));
  const int in_h = static_cast<int>(x.size(2));
  const int in_w = static_cast<int>(x.size(3));
  const int out_channels = static_cast<int>(w.size(0));
  TORCH_CHECK(w.size(1) == in_channels, "weight/input channel mismatch");
  const int kernel_h = static_cast<int>(w.size(2));
  const int kernel_w = static_cast<int>(w.size(3));
  const int out_h = static_cast<int>((in_h + 2 * padding - dilation * (kernel_h - 1) - 1) / stride + 1);
  const int out_w = static_cast<int>((in_w + 2 * padding - dilation * (kernel_w - 1) - 1) / stride + 1);
  TORCH_CHECK(out_h > 0 && out_w > 0, "invalid output size");
  auto out = torch::empty({batch, out_channels, out_h, out_w}, x.options());
  const int oc_tiles = (out_channels + OC_TILE - 1) / OC_TILE;
  const int tile_in_h = (TILE_OH - 1) * static_cast<int>(stride) + (kernel_h - 1) * static_cast<int>(dilation) + 1;
  const int tile_in_w = (TILE_OW - 1) * static_cast<int>(stride) + (kernel_w - 1) * static_cast<int>(dilation) + 1;
  const int tile_in_w_pad = (tile_in_w + 3) & ~3;
  // Double the staged buffers for the software pipeline (prefetch next chunk while
  // computing current). Input rows are padded to a multiple of 4 floats to enable
  // float4 staging.
  const size_t smem_bytes =
      2 * (static_cast<size_t>(C_CHUNK) * tile_in_h * tile_in_w_pad +
           static_cast<size_t>(OC_TILE) * C_CHUNK * kernel_h * kernel_w) * sizeof(float);
  TORCH_CHECK(smem_bytes <= 48 * 1024, "shared memory limit exceeded for this configuration");
  dim3 block(THREADS);
  dim3 grid((out_w + TILE_OW - 1) / TILE_OW,
            (out_h + TILE_OH - 1) / TILE_OH,
            batch * oc_tiles);
  TORCH_CHECK(grid.z <= 65535, "grid.z too large");
  const float* bias_ptr = has_bias ? b.data_ptr<float>() : nullptr;
  conv2d_tiled_kernel<<<grid, block, smem_bytes, at::cuda::getCurrentCUDAStream()>>>(
      x.data_ptr<float>(),
      w.data_ptr<float>(),
      bias_ptr,
      out.data_ptr<float>(),
      batch,
      in_channels,
      in_h,
      in_w,
      out_channels,
      kernel_h,
      kernel_w,
      out_h,
      out_w,
      static_cast<int>(stride),
      static_cast<int>(padding),
      static_cast<int>(dilation),
      oc_tiles,
      tile_in_h,
      tile_in_w);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return out;
}
